package com.deepanshuraj.opspilot.rag;
import jakarta.annotation.PostConstruct; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.ai.embedding.EmbeddingModel; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.core.io.support.PathMatchingResourcePatternResolver; import org.springframework.stereotype.Component;
@Component public class RagRetriever { public record Scored(KnowledgeChunk chunk,double score){} private final EmbeddingModel model; private final IngestionService ingestion; private final List<KnowledgeChunk> index=new ArrayList<>(); @Value("${opspilot.rag.chunk-size:700}") int size; @Value("${opspilot.rag.chunk-overlap:120}") int overlap; private int docs,dimension;
 public RagRetriever(EmbeddingModel m,IngestionService i){model=m;ingestion=i;} @PostConstruct void ingest() throws IOException {Set<String> seen=new HashSet<>();for(Resource r:new PathMatchingResourcePatternResolver().getResources("classpath:knowledge/*.md")){docs++;for(String text:ingestion.chunk(r.getContentAsString(StandardCharsets.UTF_8),size,overlap)){if(seen.add(ingestion.sha256(text))){float[] v=model.embed(text);dimension=v.length;index.add(new KnowledgeChunk(r.getFilename(),text,v));}}}} public List<Scored> search(String q,int k){if(index.isEmpty())return List.of();float[] v=model.embed(q);return index.stream().map(c->new Scored(c,cosine(v,c.embedding()))).sorted(Comparator.comparingDouble(Scored::score).reversed()).limit(k).toList();} private double cosine(float[] a,float[] b){double dot=0,na=0,nb=0;for(int i=0;i<a.length;i++){dot+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return na==0||nb==0?0:dot/(Math.sqrt(na)*Math.sqrt(nb));} public int getDocumentCount(){return docs;} public int getChunkCount(){return index.size();} public int getEmbeddingDimension(){return dimension;} }
